changeSet.sql:
-- super_admin: everything INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000001'::uuid, id FROM iam.permissions ON CONFLICT DO NOTHING;
-- hr_admin: everything except tenant.manage INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000002'::uuid, id FROM iam.permissions WHERE code NOT IN ('tenant.manage') ON CONFLICT DO NOTHING;
-- hr_recruiter INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000003'::uuid, id FROM iam.permissions WHERE code IN ('recruitment.manage','employee.read') ON CONFLICT DO NOTHING;
-- finance INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000004'::uuid, id FROM iam.permissions WHERE code IN ('payroll.read','payroll.run','payroll.approve', 'reimburse.approve','loan.approve','report.export','employee.read') ON CONFLICT DO NOTHING;
-- manager INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000005'::uuid, id FROM iam.permissions WHERE code IN ('leave.approve','reimburse.approve','attendance.read','employee.read') ON CONFLICT DO NOTHING;
-- employee: implicit self-access; empty explicit permissions -- auditor: read all INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000007'::uuid, id FROM iam.permissions WHERE code LIKE '%.read' OR code='audit.read' ON CONFLICT DO NOTHING;
-- it_admin INSERT INTO iam.role_permissions (role_id, permission_id) SELECT '11111111-1111-1111-1111-000000000008'::uuid, id FROM iam.permissions WHERE code IN ('tenant.manage','user.invite','user.assign_role','audit.read') ON CONFLICT DO NOTHING;
